package main

import (
	"flag"
	"fmt"
	projectcli "github.com/flidai/leapview/internal/project/cli"
	"os"
)

func main() {
	out := flag.String("out", "schemas/json", "output directory")
	flag.Parse()
	if err := projectcli.ExportSchema("json-schema", *out); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
